options.content:
flowchart TB
    OWNER(["Person<br/><b>Owner</b><br/>talks, reviews, delegates work"])
    OPERATOR(["Person<br/><b>Operator</b><br/>deploys and inspects local services"])
    AWP["Software system<br/><b>Agent Workload Platform v2</b><br/>private voice, durable tasks, owner knowledge"]
    TAILSCALE["External system<br/><b>Tailscale control plane</b><br/>device and private network identity"]
    MODELS["External system<br/><b>Remote model providers</b><br/>Pi completions"]
    INTEGRATIONS["External systems<br/><b>Optional integrations</b><br/>permission-scoped APIs"]

    OWNER -->|"uses private HTTPS, WebRTC, and owner APIs"| AWP
    OPERATOR -->|"deploys and checks local workloads"| AWP
    AWP -->|"obtains tailnet identity and network configuration"| TAILSCALE
    AWP -->|"requests Pi model completions"| MODELS
    AWP -->|"invokes configured capabilities"| INTEGRATIONS

    classDef person fill:#084c8d,color:#fff,stroke:#05345f,stroke-width:2px;
    classDef system fill:#e0f2fe,color:#0c4a6e,stroke:#0284c7,stroke-width:2px;
    classDef external fill:#6b7280,color:#fff,stroke:#374151,stroke-width:2px;
    class OWNER,OPERATOR person;
    class AWP system;
    class TAILSCALE,MODELS,INTEGRATIONS external;
